const $=s=>document.querySelector(s), artists=HC.artists;
function art(i,v=0){
  const id='grain'+i+'-'+v;
  const noise='<filter id="'+id+'"><feTurbulence type="fractalNoise" baseFrequency=".52" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".08"/></feComponentTransfer></filter>';
  let shape;
  if(i===0){
    shape='<rect width="500" height="500" fill="#ece7dc"/><rect x="29" y="30" width="442" height="440" fill="#1c1c1a"/><path d="M80 375 L212 92 L272 350 L401 124" stroke="#ede8db" stroke-width="68" fill="none"/><rect x="52" y="295" width="397" height="42" fill="#d44835" transform="rotate(-12 250 316)"/><text x="54" y="450" fill="#eee" font-family="monospace" font-size="15">EDITION / ART GRAPHIC / 001</text>';
  }else if(i===1){
    shape='<rect width="500" height="500" fill="#c7c3ee"/><circle cx="160" cy="245" r="106" fill="#212121"/><circle cx="340" cy="245" r="106" fill="#212121"/><circle cx="160" cy="245" r="83" fill="#474078"/><circle cx="340" cy="245" r="83" fill="#474078"/><path d="M239 231 Q250 216 261 231" fill="none" stroke="#f6f4eb" stroke-width="17"/><path d="M63 227 L15 200 M437 227 L485 200" fill="none" stroke="#212121" stroke-width="15"/><path d="M84 167 L190 92 M265 310 L371 235" stroke="#ffffff" stroke-width="12" opacity=".36"/><text x="42" y="452" fill="#222" font-family="monospace" font-size="15">EYEWEAR / CONCEPT VISUAL / 002</text>';
  }else{
    shape='<rect width="500" height="500" fill="#d3ff19"/><path d="M147 105 L212 73 Q250 111 288 73 L353 105 L425 202 L359 245 L326 201 L326 435 L174 435 L174 201 L141 245 L75 202 Z" fill="#f2f1ea" stroke="#111" stroke-width="4"/><text x="250" y="259" font-family="Arial" font-weight="900" font-size="47" text-anchor="middle" fill="#151515" transform="rotate(-6 250 259)">SIMPLE</text><text x="250" y="309" font-family="Arial" font-weight="900" font-size="52" text-anchor="middle" fill="#151515" transform="rotate(-6 250 309)">LIFE</text><text x="45" y="472" fill="#222" font-family="monospace" font-size="15">TEXTILE / MOCK-UP / 003</text>';
  }
  return '<div class="visual" role="img" aria-label="Illustration fictive d’ambiance pour '+artists[i].name+' ; aucun produit réel représenté"><svg viewBox="0 0 500 500" xmlns="http://www.w3.org/2000/svg"><defs>'+noise+'</defs>'+shape+'<rect width="500" height="500" filter="url(#'+id+')" opacity=".7"/></svg></div>';
}
function cards(){return `<div class="artists">${artists.map((a,i)=>`<a class="artcard" href="#/artiste/${a.id}">${art(i)}<div class="meta"><div><h3>${a.name}</h3><span class="label">${a.discipline}</span></div><span>↗</span></div></a>`).join('')}</div>`}
function program(){return HC.program.map(p=>`<div class="row"><span class="time">${p[0]}</span><div><h3>${p[1]}</h3><p>${p[2]}</p></div><span class="label">${p[3]}</span></div>`).join('')}
function head(n,t,p=''){return `<div class="pagehead"><span class="eyebrow">HORS CADRE / ${n}</span><h1>${t}</h1><p>${p}</p></div>`}
function closing(){return `<section class="section closing"><h2>ON SE VOIT<br>HORS CADRE ?</h2><div><a class="btn" href="https://shotgun.live/fr" target="_blank" rel="noopener">Prendre ma place ↗</a><p class="notice">Démo : lien vers l’accueil Shotgun.<br>Aucun billet pour cet événement fictif.</p></div></section>`}
function home(){return `<section class="hero"><div class="eyebrow"><span class="dot">Cultures libres · Marseille</span><span>Art / Musique / Pop-up / Bar</span></div><h1 class="wordmark">HORS CADRE</h1><div class="heroimage"><img src="assets/live.jpg" alt="Foule et faisceaux lumineux en concert, photographie d’ambiance"><div class="badge">ÉDITION<strong>001</strong>MARSEILLE</div><div class="herocopy"><h2>LA VILLE DÉBORDE.<br>NOUS AUSSI.</h2><p>Trois artistes. Des collections singulières.<br>Un lieu brut, des idées libres. Et vous.</p><a class="btn" href="#/concept">Explorer l’événement <span>↗</span></a></div></div><div class="hero-bottom"><span>SAMEDI · DATE À VENIR<br>16:00 — 00:00</span><span>MARSEILLE, LIEU INDUSTRIEL<br>ADRESSE À CONFIRMER</span><a class="textlink" href="#/popup">Trois univers. Un même terrain de jeu. ↗</a></div></section><div class="ticker"><span>ART SANS FRONTIÈRES</span><span>✳</span><span>SONS SANS ÉTIQUETTES</span><span>✳</span><span>MARSEILLE SANS FILTRE</span></div><section class="section intro"><span class="label">01 / LE MANIFESTE</span><div><h2>Sortir des lignes.<br>Faire place aux rencontres.</h2><p>HORS CADRE investit un bâtiment industriel marseillais le temps d’une journée et d’une nuit. L’art s’expose, les basses circulent, les créations changent de mains. Un rendez-vous indépendant pour celles et ceux qui font bouger la ville.</p><a class="textlink" href="#/concept">Lire le manifeste ↗</a></div></section><section class="section"><div class="section-head"><h2>Trois artistes. Trois univers.</h2><a href="#/popup" class="textlink">ENTRER DANS LE POP-UP ↗</a></div>${cards()}</section><section class="section night"><div class="section-head"><h2>Du jour jusqu’à la nuit.</h2><span class="label">16:00 → 00:00</span></div>${program()}<p class="notice">Programmation fictive pour la démonstration.</p></section>${closing()}`}
function concept(){return head('01 / LE CONCEPT','LA CULTURE<br>EN MOUVEMENT.','Un événement indépendant. Quatre univers qui se croisent. Une autre façon de vivre Marseille.')+`<section class="section intro"><span class="label">LE MANIFESTE</span><div><h2>Pas de frontières<br>entre les disciplines.</h2><p>Nous croyons aux rencontres qui ne sont pas prévues. À une photographie découverte entre deux morceaux. À une conversation au bar qui devient une collaboration. HORS CADRE donne un terrain commun aux artistes émergents et aux publics curieux.</p><p>Le lieu : un bâtiment industriel réinvesti à Marseille, choisi pour son caractère brut. Le lieu définitif et les informations d’accès seront annoncés avant toute ouverture réelle de billetterie.</p></div></section><section class="section info-grid">${[['01 / ART','Des murs aux regards','Sérigraphie, photographie et installations : trois façons de raconter le territoire.'],['02 / MUSIQUE','Les sons de la ville','Hip-hop, rap, neo-soul et bass music. Une progression du warm-up au dernier set.'],['03 / POP-UP','De l’artiste à vous','Petites éditions, textiles et objets indépendants. Découvrez les histoires derrière les créations.'],['04 / BAR','Le point de rencontre','Un espace pour se retrouver et prendre le temps. Boissons avec et sans alcool au programme.']].map(x=>`<article><span class="label">${x[0]}</span><h2>${x[1]}</h2><p>${x[2]}</p></article>`).join('')}</section><section class="section night"><div class="section-head"><h2>Le programme / 001</h2><span class="label">SAMEDI · DATE À VENIR</span></div>${program()}<p class="notice">Artistes musicaux fictifs. Fin de l’événement à minuit.</p></section>${closing()}`}
function products(a,i){
  return '<section class="section shop-section"><div class="section-head"><h2>LA COLLECTION / 00'+(i+1)+'</h2><span class="label">'+a.products.length+' OBJETS / SÉLECTION</span></div>'
    +'<div class="shop-intro"><p>La sélection de '+a.name+' : une vitrine de créations indépendantes. Les illustrations, descriptions, stocks et tarifs sont provisoires, uniquement pour la démonstration.</p><span>HORS CADRE — POP-UP STORE ↗</span></div>'
    +'<div class="products">'+a.products.map((p,j)=>'<article class="product"><div class="product-top"><span class="product-index">HC / '+String(j+1).padStart(2,'0')+'</span><span class="product-type">'+a.name+'</span></div>'
      +art(i,j+1)+'<h3>'+p.name+'</h3><p class="product-desc">'+p.desc+'</p><div class="label product-availability">'+(p.stock?'Disponible / simulation':'Épuisé / simulation')+'</div>'
      +'<button class="buy" data-buy="'+i+','+j+'" '+(p.stock?'':'disabled')+'><span>'+(p.stock?'Voir l’achat simulé ↗':'Indisponible')+'</span><span>'+p.price+' €</span></button></article>').join('')
    +'</div><p class="notice">Catalogue d’exemple. Aucun paiement, aucune commande et aucune vente réelle.</p></section>';
}
function bio(a,i,full=false){return `<section class="section artist-intro">${art(i)}<div><span class="label">${a.discipline} / Marseille</span><h2>${a.name}</h2><p>${a.bio}</p><p class="notice">Texte et visuel illustratifs · Biographie et produits à valider avec l’artiste ou la marque.</p>${full?`<a class="textlink" href="#/popup">← Retour au pop-up</a>`:`<a class="textlink" href="#/artiste/${a.id}">Découvrir l’artiste et sa collection ↗</a>`}</div></section>${products(a,i)}`}
let selected=0,edition=0;
function popup(){return head('02 / LE POP-UP','L’ART À EMPORTER.','Des petites séries, des grandes idées. Rencontrez les trois artistes de l’édition 001 et explorez leurs créations.')+`<div class="tabs" role="tablist" aria-label="Artistes">${artists.map((a,i)=>`<button role="tab" id="artist-tab-${i}" aria-controls="artist-panel" aria-selected="${selected===i}" tabindex="${selected===i?0:-1}" data-artist="${i}">${a.name}</button>`).join('')}</div><div id="artist-panel" role="tabpanel" aria-labelledby="artist-tab-${selected}">${bio(artists[selected],selected)}</div>`}
function archives(){
  const header=head('03 / LES ARCHIVES','ÇA LAISSE<br>DES TRACES.','Un journal visuel des éditions, des rencontres et des nuits. Les photographies réelles seront ajoutées après l’événement.');
  const tabs='<div class="tabs" role="tablist" aria-label="Éditions"><button role="tab" aria-selected="'+(edition===0)+'" data-edition="0">Édition 001</button><button role="tab" aria-selected="'+(edition===1)+'" data-edition="1">Édition 000 · Démo</button></div>';
  if(edition===0)return header+tabs+'<section class="section"><div class="empty"><span class="label">ARCHIVES / 001 — COMING SOON</span><h2>LE NUMÉRO RESTE À ÉCRIRE.</h2><p>Les photographies de la première édition rejoindront ce journal après l’événement.</p><button class="btn" data-edition="1">Feuilleter la maquette d’archives ↗</button></div></section>';
  const titles=['MOUVEMENTS — La foule','APRÈS LA NUIT — Les lumières','HORS CHAMP — Les détails'];
  const captions=titles.map((title,i)=>'<button class="'+(i===1?'gallery-small':i===2?'gallery-wide':'')+'" data-photo="'+i+'" aria-label="Agrandir : '+title+'"><figure><img src="assets/live.jpg" alt="Photo de concert illustrative, recadrée pour maquette éditoriale" style="object-position:'+(i*30+15)+'% '+(i===2?'72':'50')+'%;'+(i===1?'transform:scaleX(-1)':'')+'"><figcaption><span>0'+(i+1)+' / '+title+'</span><span>↗</span></figcaption></figure></button>').join('');
  return header+tabs+'<section class="archive-feature"><div class="section-head"><div><span class="archive-kicker">PHOTO JOURNAL / MAQUETTE</span><h2>LES NUITS<br>EN IMAGES.</h2></div><span class="issue-number">ÉDITION 000<br>ARCHIVE FICTIVE</span></div><div class="gallery-mag">'+captions+'</div><p class="notice">Ces trois cadres utilisent la même photographie illustrative Unsplash. Il ne s’agit pas de photographies d’un événement HORS CADRE.</p></section>';
}
function infos(){return head('04 / INFOS PRATIQUES','ON SE RETROUVE OÙ ?','Les premières informations de l’édition 001. Ce projet est fictif : aucune réservation n’est ouverte.')+`<section class="section info-grid">${[['Date & horaires','Un samedi, date à confirmer.<br>Ouverture à 16 h. Fin à minuit.'],['Lieu & accès','Bâtiment industriel réinvesti à Marseille.<br>Adresse, transports et accès vélo à venir.'],['Billets & entrée','Tarif de travail : 18 € (hypothèse pédagogique).<br>Le bouton Billetterie mène à l’accueil Shotgun. Aucun billet HORS CADRE n’est en vente.'],['Accessibilité','Les conditions d’accès PMR, les sanitaires et les aménagements seront précisés une fois le lieu validé.'],['Sur place','Exposition, pop-up, musique et espace bar.<br>Une sélection de boissons sans alcool est prévue.'],['Contact & réseaux','Coordonnées et comptes officiels à venir.<br>Aucun contact ni compte d’artiste fictif n’est présenté comme réel.']].map(x=>`<article><h2>${x[0]}</h2><p>${x[1]}</p></article>`).join('')}</section>`}
function legal(){return head('INFORMATIONS','LE CADRE<br>DE LA DÉMO.')+`<section class="section legal"><h2>Projet fictif</h2><p>HORS CADRE est un prototype pédagogique. Les noms des trois artistes / marques sont fournis pour le projet ; leurs biographies, visuels et produits ici montrés sont des contenus fictifs de démonstration, sans approbation officielle. Le lieu, la date et la commercialisation ne sont pas confirmés.</p><h2>Achats & billetterie</h2><p>Les boutons d’achat ouvrent une simulation sans paiement, sans commande et sans collecte de coordonnées. Le lien Shotgun ouvre l’accueil de la plateforme externe, dont les propres conditions s’appliquent.</p><h2>Données personnelles</h2><p>Ce prototype n’intègre aucun formulaire, traceur publicitaire ou outil d’analyse. Aucun compte utilisateur n’est créé et aucune donnée bancaire n’est demandée.</p><h2>Crédits visuels</h2><p>Photographie d’ambiance : <a class="textlink" href="https://images.unsplash.com/photo-1470229722913-7c0e2dbbafd3" target="_blank" rel="noopener">source photographique Unsplash ↗</a>. Les compositions graphiques et les représentations de produits sont des illustrations créées pour cette démonstration. Les archives 000 utilisent des cadrages de la même photo.</p><h2>Avant une exploitation réelle</h2><p>Les mentions d’éditeur, l’identité du vendeur, les crédits photographiques complets, les conditions de vente, la politique de confidentialité et les modalités de billetterie devront être complétés et validés.</p></section>`}
function render(focus=false){let path=location.hash.slice(1)||'/';let html;if(path==='/')html=home();else if(path==='/concept')html=concept();else if(path==='/popup')html=popup();else if(path==='/archives')html=archives();else if(path==='/infos')html=infos();else if(path==='/mentions')html=legal();else if(path.startsWith('/artiste/')){let i=artists.findIndex(a=>a.id===path.split('/')[2]);html=i<0?head('404','PAGE INTROUVABLE.'):head('LE POP-UP / '+artists[i].name,'DANS L’UNIVERS<br>DE '+artists[i].name)+bio(artists[i],i,true)}else html=head('404','HORS PISTE.','Cette page n’existe pas.')+'<section class="section"><a class="btn" href="#/">Retour à l’accueil ↗</a></section>';$('#main').innerHTML=html;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+path));$('nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');document.title='HORS CADRE — '+(path==='/'?'Cultures libres, Marseille':path.split('/').pop().toUpperCase());if(focus){window.scrollTo(0,0);$('#main').focus({preventScroll:true})}}
window.addEventListener('hashchange',()=>render(true));$('.menu').onclick=()=>{const open=$('nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String(open))};$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});document.addEventListener('click',e=>{let t=e.target.closest('[data-artist],[data-buy],[data-edition],[data-photo]');if(!t)return;if(t.dataset.artist!==undefined){selected=+t.dataset.artist;render();$(`[data-artist="${selected}"]`).focus()}if(t.dataset.edition!==undefined){edition=+t.dataset.edition;render();$(`[data-edition="${edition}"]`).focus()}if(t.dataset.buy){let [i,j]=t.dataset.buy.split(',').map(Number),p=artists[i].products[j];$('#modal-content').innerHTML=`<span class="modal-label">SIMULATION D’ACHAT / ${artists[i].name}</span><h2>${p.name}</h2><p>${p.desc}</p><h3>${p.price} €</h3><p>Cette création fait partie d’un catalogue fictif. Aucun paiement ne sera demandé et aucune commande ne sera enregistrée.</p><button class="btn" id="continue">Continuer la découverte ↗</button>`;$('#modal').showModal();$('#continue').onclick=()=>$('#modal').close()}if(t.dataset.photo!==undefined){$('#modal-content').innerHTML='<img src="assets/live.jpg" alt="Vue agrandie de la photographie de concert illustrative"><p class="notice">Édition 000 · Galerie fictive · Photographie d’ambiance Unsplash.</p>';$('#modal').showModal()}});document.addEventListener('keydown',e=>{if(e.target.matches('[data-artist]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();selected=e.key==='Home'?0:e.key==='End'?2:(selected+(e.key==='ArrowRight'?1:2))%3;render();$(`[data-artist="${selected}"]`).focus()}});render();

$(".skip").addEventListener("click",e=>{e.preventDefault();$("#main").focus()});
